-- Platform layer (docs/architecture.md): projects, the Pac and content kind of each uploaded file, follows with
-- Auto-Stacc, and generic polls. Forward-only; nothing existing is rewritten. Projects and polls are synced from
-- data/ by db/catalog.sql (generated by scripts/build.js), like products.

-- Products know their project and the Pacs they deliver (JSON list of Pac ids from data/pacs.js).
ALTER TABLE products ADD COLUMN project_id TEXT;
ALTER TABLE products ADD COLUMN pacs TEXT NOT NULL DEFAULT '[]';

-- An uploaded file is an asset: which of its product's Pacs it belongs to, and its content kind (data/content-types.js).
-- Both optional: files uploaded before this, or without a Pac, are still delivered under their product.
ALTER TABLE product_files ADD COLUMN pac_id TEXT;
ALTER TABLE product_files ADD COLUMN kind TEXT NOT NULL DEFAULT '';

CREATE TABLE projects (
  id TEXT PRIMARY KEY,
  name TEXT NOT NULL,
  features TEXT NOT NULL DEFAULT '[]',
  published INTEGER NOT NULL DEFAULT 0,
  catalog_hash TEXT,
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL,
  deleted_at TEXT
);

-- A verified account following a project. auto_stacc = 1: free products of the project are granted automatically.
CREATE TABLE follows (
  user_id TEXT NOT NULL,
  project_id TEXT NOT NULL REFERENCES projects(id),
  auto_stacc INTEGER NOT NULL DEFAULT 0,
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL,
  PRIMARY KEY (user_id, project_id)
);
CREATE INDEX follows_project ON follows(project_id);

-- Generic polls; a project uses them only if its features include "polls". options: JSON [{ id, label }].
CREATE TABLE polls (
  id TEXT PRIMARY KEY,
  project_id TEXT NOT NULL,
  question TEXT NOT NULL,
  options TEXT NOT NULL DEFAULT '[]',
  opens_at TEXT,
  closes_at TEXT,
  published INTEGER NOT NULL DEFAULT 0,
  catalog_hash TEXT,
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL,
  deleted_at TEXT
);

-- One vote per verified account per poll, changeable while the poll is open.
CREATE TABLE poll_votes (
  poll_id TEXT NOT NULL REFERENCES polls(id),
  user_id TEXT NOT NULL,
  option_id TEXT NOT NULL,
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL,
  PRIMARY KEY (poll_id, user_id)
);
